:root {
  --card-bg: #1a1025;
  --header-bg: #2d1f45;
  --accent: #c084fc;
  --accent-dark: #7c3aed;
  --text-primary: #f3e8ff;
  --text-secondary: #c4b5d4;
  --text-muted: #8b7aa0;
  --amount-bg: #3b2860;
  --amount-color: #e2c9ff;
  --step-num-bg: #7c3aed;
  --step-num-color: #ffffff;
  --meta-bg: #2d1f45;
  --divider: #3b2860;
  --badge-bg: #c084fc;
  --badge-text: #1a1025;
}

.card {
  width: 500px;
  background-color: var(--card-bg);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--divider);
}

.card-header {
  background-color: var(--header-bg);
  padding: 16px 20px;
  border-bottom: 1px solid var(--divider);
}

.badge {
  display: inline-block;
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 20px;
  margin-bottom: 8px;
}

.drink-name {
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0 0 4px 0;
  line-height: 1.1;
}

.drink-sub {
  font-size: 13px;
  color: var(--text-muted);
  margin: 0;
  letter-spacing: 0.05em;
}

.card-body {
  display: flex;
  gap: 0;
}

.ingredients-panel {
  flex: 1;
  padding: 16px 20px;
  border-right: 1px solid var(--divider);
}

.details-panel {
  flex: 1;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.section-title {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  margin: 0 0 10px 0;
}

.ingredient-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ingredient-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.amount {
  background-color: var(--amount-bg);
  color: var(--amount-color);
  font-size: 11px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 6px;
  white-space: nowrap;
  min-width: 54px;
  text-align: center;
}

.ingredient {
  font-size: 13px;
  color: var(--text-secondary);
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.step {
  display: flex;
  align-items: center;
  gap: 9px;
}

.step-num {
  width: 20px;
  height: 20px;
  background-color: var(--step-num-bg);
  color: var(--step-num-color);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.step-text {
  font-size: 13px;
  color: var(--text-secondary);
}

.meta-row {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.meta-item {
  flex: 1;
  background-color: var(--meta-bg);
  border-radius: 10px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-items: center;
}

.meta-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

.meta-value {
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
}
